const { throwAuthenticationError } = require('@open-condo/keystone/apolloErrorFormatter')
const { find } = require('@open-condo/keystone/schema')

const { CONTEXT_FINISHED_STATUS } = require('@condo/domains/miniapp/constants')
const { getEmployedOrganizationsByPermissions } = require('@condo/domains/organization/utils/accessSchema')
const { canDirectlyManageSchemaObjects, canDirectlyReadSchemaObjects } = require('@condo/domains/user/utils/directAccess')

/**
 * AISkills read access is enforced server-side by scope:
 * 1. Admin / support → all skills
 * 2. Direct access users → all skills
 * 3. Any authed user → public global, organization, personal, and connected B2BApp skills available to them
 */
async function getUserAISkillsFilter (context, user) {
    const employedOrganizationIds = await getEmployedOrganizationsByPermissions(context, user, [])
    const appContexts = await find('B2BAppContext', {
        organization: { id_in: employedOrganizationIds },
        status: CONTEXT_FINISHED_STATUS,
        deletedAt: null,
        app: { deletedAt: null },
    })
    const connectedAppIds = [...new Set(appContexts.map(appContext => appContext.app).filter(Boolean))]

    return {
        isPublic: true,
        OR: [
            { scope: 'global' },
            { scope: 'organization', organization: { id_in: employedOrganizationIds } },
            { scope: 'personal', user: { id: user.id } },
            { scope: 'b2bApp', b2bApp: { id_in: connectedAppIds } },
        ],
    }
}

async function canReadAISkills ({ authentication: { item: user }, context, listKey }) {
    if (!user) return throwAuthenticationError()
    if (user.deletedAt) return false
    if (user.isAdmin || user.isSupport) return {}

    const hasDirectAccess = await canDirectlyReadSchemaObjects(user, listKey)
    if (hasDirectAccess) return {}

    return await getUserAISkillsFilter(context, user)
}

/**
 * AISkills can be managed by:
 * 1. Admin / support
 * 2. Users with direct access
 */
async function canManageAISkills ({ authentication: { item: user }, listKey, originalInput, operation }) {
    if (!user) return throwAuthenticationError()
    if (user.deletedAt) return false
    if (user.isSupport || user.isAdmin) return true

    return await canDirectlyManageSchemaObjects(user, listKey, originalInput, operation)
}

/*
  Rules are logical functions that used for list access, and may return a boolean (meaning
  all or no items are available) or a set of filters that limit the available items.
*/
module.exports = {
    canReadAISkills,
    canManageAISkills,
    getUserAISkillsFilter,
}
